"use client";

import { getProject, types, type ISheet } from "@theatre/core";
import state from "@/data/theatre/chamber.json";
import pose from "@/data/theatre/resting-pose.json";

/*
 * The Theatre.js project for the temporal chamber. The state is generated by
 * scripts/theatre-state.mjs (and refined, when wanted, in Studio during
 * development); this module only binds it to typed objects and exposes the
 * live values to the render loop through one mutable record.
 *
 * Ownership: Theatre owns the camera's base position and fov, the artifact's
 * scale, distortion, pulse, hue and spin, the orbitals' tilt and spread, and
 * the light. Pointer parallax and scroll dolly are added on top in the camera
 * rig, in their own offsets, so no property has two authors.
 */

export const RANGES = {
  entrance: [0, 4],
  event: [4.5, 8],
} as const satisfies Record<string, readonly [number, number]>;

export type ChamberValues = typeof pose;
export const restingPose: ChamberValues = pose;

interface Chamber {
  sheet: ISheet;
  /** Mutated by Theatre on every change; read it in useFrame, never copy it into React state. */
  values: ChamberValues;
  ready: Promise<void>;
}

let chamber: Chamber | null = null;

/** The sheet and its live values, created once for the page. */
export function getChamber(): Chamber {
  if (chamber) return chamber;
  const project = getProject("CHRONOS", { state });
  const sheet = project.sheet("Temporal chamber");
  const values: ChamberValues = structuredClone(pose);
  const num = (value: number, range: [number, number]) => types.number(value, { range });

  const camera = sheet.object("camera", {
    x: num(pose.camera.x, [-4, 4]),
    y: num(pose.camera.y, [-4, 4]),
    z: num(pose.camera.z, [2, 16]),
    fov: num(pose.camera.fov, [20, 60]),
  });
  const artifact = sheet.object("artifact", {
    scale: num(pose.artifact.scale, [0, 2]),
    distortion: num(pose.artifact.distortion, [0, 1]),
    pulse: num(pose.artifact.pulse, [0, 1]),
    hue: num(pose.artifact.hue, [0, 1]),
    spin: num(pose.artifact.spin, [0, 2]),
  });
  const orbitals = sheet.object("orbitals", {
    tilt: num(pose.orbitals.tilt, [0, 2]),
    spread: num(pose.orbitals.spread, [0, 1]),
  });
  const light = sheet.object("light", { intensity: num(pose.light.intensity, [0, 3]) });

  camera.onValuesChange((v) => Object.assign(values.camera, v));
  artifact.onValuesChange((v) => Object.assign(values.artifact, v));
  orbitals.onValuesChange((v) => Object.assign(values.orbitals, v));
  light.onValuesChange((v) => Object.assign(values.light, v));

  chamber = { sheet, values, ready: project.ready.then(() => undefined) };
  return chamber;
}

/** Plays one of the named ranges from its start; resolves when it ends (or is interrupted). */
export async function playRange(range: readonly [number, number], rate = 1): Promise<boolean> {
  const { sheet, ready } = getChamber();
  await ready;
  sheet.sequence.position = range[0];
  return sheet.sequence.play({ range: [range[0], range[1]], rate });
}

/** Holds the resting pose without playing anything (effects reduced, Theatre switched off). */
export async function holdRest(): Promise<void> {
  const { sheet, ready } = getChamber();
  await ready;
  sheet.sequence.pause();
  sheet.sequence.position = RANGES.entrance[1];
}
